    meta_page_title: "AAB1 Engineering Ecosystem: Agentic Architecture, DevSecOps & Cloud | AAB1",
    meta_hero_badge: "Corporate Architecture · Software Engineering, AI & Multi-Cloud",
    meta_hero_std_badge: "🛡️ Zero-Trust DevSecOps · OIDC Federation · Multi-Cloud",
    meta_hero_title_1: "Agentic Control Plane,",
    meta_hero_title_gradient: "DevSecOps & Cloud Governance",
    meta_hero_desc: "The <strong>AAB1 Engineering Ecosystem</strong> is the corporate architecture orchestrating our software factory and cloud operations. It integrates coordination assisted by <strong>AI Meta-Agents and specialized Subagents</strong>, <strong>Zero-Trust GitHub Actions CI/CD pipelines</strong> with keyless OIDC identity federation, <strong>real-time FinOps budget governance</strong>, and regulatory compliance across <strong>Google Cloud Platform (GCP), Firebase, AWS, and Oracle Cloud Infrastructure (OCI)</strong>.",
    meta_pillars_title_1: "The 4 Engineering Pillars of the",
    meta_pillars_title_gradient: "AAB1 Ecosystem",
    meta_pillars_subtitle: "Industry standards and verifiable engineering practices uniformly enforced across every platform, microservice, and SaaS solution.",
    meta_p1_badge: "MCP Protocol + Multi-Agent + ADRs",
    meta_p1_title: "1. AI Meta-Agents, Subagents & MCP Protocol",
    meta_p1_li1: "<strong>Centralized Architectural Orchestration:</strong> A meta-agent system coordinates requirement traceability, domain rule consistency, and Architecture Decision Records (ADRs) across the software lifecycle.",
    meta_p1_li2: "<strong>Subagents with Separation of Duties:</strong> Specialized agents for hexagonal architecture validation, API interoperability contracts, test-driven development (TDD), and automated security auditing on every code review.",
    meta_p1_li3: "<strong>Human-in-the-Loop Governance:</strong> Language models operate under role-based access controls (RBAC) via the Model Context Protocol (MCP) standard, requiring explicit human approval for critical changes or production releases.",
    meta_p2_badge: "Zero-Trust DevSecOps + OIDC Federation",
    meta_p2_title: "2. DevSecOps Engineering, CI/CD & OIDC Federation",
    meta_p2_li1: "<strong>Keyless Cloud Authentication:</strong> Automated deployments from GitHub Actions to Google Cloud Platform and AWS use <strong>Workload Identity Federation (OIDC)</strong> via short-lived ephemeral credentials.",
    meta_p2_li2: "<strong>Automated Security Pipelines:</strong> Preventive secret detection, static application security testing (SAST), software composition analysis (SCA), container and infrastructure-as-code (IaC) scanning, and change control with mandatory reviews.",
    meta_p2_li3: "<strong>Runtime Hardening:</strong> Enforcement of Content Security Policies (<strong>CSP</strong>), HTTP Strict Transport Security (<strong>HSTS</strong>), <strong>Firebase App Check</strong>, least-privilege access, and credential custody in cloud secret managers (<strong>Secret Manager / KMS</strong>).",
    meta_p3_badge: "FinOps Governance + BigQuery",
    meta_p3_title: "3. Multi-Cloud FinOps Governance & AI Telemetry",
    meta_p3_li1: "<strong>Transactional Budget Control:</strong> Real-time quota and spending cap management per organization, project, and operating environment (development, staging, and production).",
    meta_p3_li2: "<strong>Google BigQuery Cost Analytics:</strong> Consolidation and export of cloud consumption metrics, continuous monitoring of AI token and inference usage, and early anomaly detection.",
    meta_p3_li3: "<strong>Dynamic Model Optimization (Right-Sizing):</strong> Intelligent routing across AI models (Google Gemini, Vertex AI, and foundation models), semantic caching, and policy-as-code evaluation.",
    meta_p4_badge: "Continuous Improvement + Hexagonal Architecture",
    meta_p4_title: "4. Continuous Improvement & Multi-Cloud Portability",
    meta_p4_li1: "<strong>Closed-Loop Quality System:</strong> Findings from technical audits and operational reviews are systematically incorporated as automated continuous integration rules and regression test suites.",
    meta_p4_li2: "<strong>Hexagonal Architecture & IaC:</strong> Strict decoupling between business logic and cloud providers, applying authenticated per-organization encryption and declarative provisioning with Terraform / OpenTofu.",
    meta_p4_li3: "<strong>Privacy & Compliance by Design:</strong> Verifiable consent management, immutable audit traceability (WORM), and data protection controls aligned with international standards.",
    meta_modules_title_1: "Core Solutions & Capabilities of the",
    meta_modules_title_gradient: "AAB1 Ecosystem",
    meta_modules_subtitle: "Enterprise-grade modular capabilities powering AAB1's commercial platforms and consulting engagements on Google Cloud, Firebase, AWS, and OCI.",
    meta_mod_seg_title: "Corporate DevSecOps & Zero-Trust CI/CD Framework",
    meta_mod_seg_desc: "Standardized GitHub Actions workflows, CSP/HSTS web hardening templates, OIDC identity federation, and continuous automated auditing of code, dependencies, containers, and infrastructure.",
    meta_mod_finops_title: "Cloud & AI FinOps Governance Platform",
    meta_mod_finops_desc: "Multi-project budget control engine, real-time Artificial Intelligence quota consumption monitoring, and analytical export to Google BigQuery.",
    meta_mod_wam_title: "Enterprise WhatsApp Cloud API & OTP Gateway",
    meta_mod_wam_desc: "Modular service on Google Cloud Run integrated with Meta's official WhatsApp Business API for transactional notifications, secure one-time password (OTP) verification, and SMS fallback.",
    meta_mod_rag_title: "Enterprise AI Assistant & RAG Engine",
    meta_mod_rag_desc: "Retrieval-Augmented Generation (RAG) architecture with Google Gemini and Vertex AI, per-client semantic data isolation, language detection, and conversational safety controls.",
    meta_mod_qr_title: "QR Simple Payment & Reconciliation Gateway",
    meta_mod_qr_desc: "Transactional component for automated generation and verification of interoperable EMVCo QR Simple payments in Bolivia, integrated with financial APIs, digital wallets, and Firebase reconciliation.",
    meta_mod_fenc_title: "Electronic Signature & WORM Custody SaaS Engine",
    meta_mod_fenc_desc: "B2B digital signature platform for PDF documents under the PAdES standard, asymmetric key management in cloud KMS services, certified timestamping (TSA), and immutable evidence archiving.",
    meta_mod_ekyc_title: "Digital Onboarding & Biometrics Middleware (eKYC)",
    meta_mod_ekyc_desc: "Serverless document verification and facial liveness biometric inspection service with portable hexagonal architecture across Google Cloud and AWS, and end-to-end encryption.",
    meta_mod_learn_title: "Continuous Improvement & Software Quality System",
    meta_mod_learn_desc: "Quality assurance framework institutionalizing OWASP best practices, architecture reviews, and automated testing across the AI-assisted development lifecycle.",
    meta_mod_oci_title: "Oracle Cloud Infrastructure (n8n, Odoo ERP & PostgreSQL)",
    meta_mod_oci_desc: "Enterprise virtual machine compute environments on Oracle Cloud Infrastructure (OCI) hosting n8n automation and AI workflow orchestration, Odoo ERP business management, and transactional PostgreSQL databases with automated backups.",
